/**
 * Puts a removed member back on the same row: the new invitation's role and
 * inviter, with the acceptance time as the join date. They hold a seat again.
 */
export async function reinstateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  joinedAt: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(),
      role,
      status: "active",
      invitedBy,
      joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

