import type { Actor, Invitation, Member, Role } from "@/types/member";

/** Default validity of a freshly minted invitation, in days. */
const DEFAULT_EXPIRY_DAYS = 14;

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * A batch that names a current member, a still-pending invite, or the same
 * address twice is refused as a whole — nothing is written. Comparison ignores
 * letter case. A former member, or an address whose earlier invite expired or
 * was revoked, may be invited again.
 */
async function assertInvitesAreOpen(
  orgId: InviteMembersInput["orgId"],
  invites: readonly { email: string; role: Role }[],
): Promise<void> {
  const seen = new Set<string>();

  for (const invite of invites) {
    const email = normalizeEmail(invite.email);
    if (seen.has(email)) {
      throw new Error(
        `Cannot invite ${email} more than once in the same batch`,
      );
    }
    seen.add(email);

    const member = await memberRepo.findActiveMemberByEmail(orgId, email);
    if (member) {
      throw new Error(`${email} is already a member of this workspace`);
    }

    const pending = await invitationRepo.findPendingInvitationByEmail(
      orgId,
      email,
    );
    if (pending) {
      throw new Error(`${email} already has a pending invitation`);
    }
  }
}

