  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That workspace no longer exists");
  }

  const user = await userRepo.findUserById(userId);
  if (
    !user ||
    user.email.toLowerCase() !== invitation.email.toLowerCase()
  ) {
    throw new Error("That invitation was sent to a different email address");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMembership(invitation.orgId, userId);

  let member: Member;
  let joined = false;

  if (existing && existing.archivedAt === null && existing.status === "active") {
    member = existing;
  } else if (existing) {
    member = await memberRepo.reinstateMember(
      invitation.orgId,
      existing.id,
      invitation.role,
      invitation.invitedBy,
      acceptedAt,
    );
    joined = true;
  } else {
    member = await memberRepo.insertMember(
      invitation.orgId,
      userId,
      invitation.role,
      invitation.invitedBy,
    );
    joined = true;
  }

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  if (joined) {
    await emit("member.joined", {
      ...envelope(invitation.orgId, userId),
      memberId: member.id,
      userId,
      role: member.role,
    });
  }

  await recomputeUsage(invitation.orgId);
  return member;
}

