export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

input.new_string:
export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  const principal = await sessionRepo.findSessionByTokenHash(hashToken(token));
  if (!principal || principal.activeOrgId === null) return principal;

  const org = await orgRepo.findOrgById(principal.activeOrgId);
  const member =
    org && org.archivedAt === null
      ? await memberRepo.findMember(org.id, principal.userId)
      : null;

  if (member && member.status === "active") return principal;

  await retargetSessionsAwayFromOrg(principal.activeOrgId, principal.userId);
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * Sessions that default to `orgId` stop doing so. Each one is pointed at
 * another workspace that user still belongs to, or cleared when they have
 * none. Sessions aimed at a different workspace are left alone, as are other
 * users when `userId` is passed.
 */
export async function retargetSessionsAwayFromOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<void> {
  const rows = await sessionRepo.listSessionsForOrg(orgId, userId);
  const nextByUser = new Map<UserId, OrgId | null>();

  for (const row of rows) {
    let next = nextByUser.get(row.userId);
    if (next === undefined) {
      const orgs = await orgRepo.listOrgsForUser(row.userId);
      next = orgs.find((org) => org.id !== orgId)?.id ?? null;
      nextByUser.set(row.userId, next);
    }
    await sessionRepo.setActiveOrg(row.id, next);
  }
}

